//! Minimal SPA pod marshalling for the Audio Center.
//!
//! Pods are the binary blobs PipeWire uses for node/device parameters. Only
//! the shapes this app needs are implemented (objects with primitive props,
//! float/id arrays), and the builder output is byte-for-byte identical to the
//! C `spa_pod_builder` — the unit tests below pin the layout using reference
//! bytes generated by the official C builder.

const std = @import("std");
const assert = std.debug.assert;

// ── type ids (spa/utils/type.h) ─────────────────────────────────────────────

pub const TYPE_NONE: u32 = 1;
pub const TYPE_BOOL: u32 = 2;
pub const TYPE_ID: u32 = 3;
pub const TYPE_INT: u32 = 4;
pub const TYPE_LONG: u32 = 5;
pub const TYPE_FLOAT: u32 = 6;
pub const TYPE_DOUBLE: u32 = 7;
pub const TYPE_STRING: u32 = 8;
pub const TYPE_ARRAY: u32 = 13;
pub const TYPE_STRUCT: u32 = 14;
pub const TYPE_OBJECT: u32 = 15;

// object param types (spa/utils/type.h, SPA_TYPE_OBJECT_START = 0x40000)
pub const OBJECT_Props: u32 = 0x40002;
pub const OBJECT_Format: u32 = 0x40003;
pub const OBJECT_ParamProfile: u32 = 0x40007;
pub const OBJECT_ParamRoute: u32 = 0x40009;

// param ids (spa/param/param.h)
pub const PARAM_Props: u32 = 2;
pub const PARAM_EnumFormat: u32 = 3;
pub const PARAM_Format: u32 = 4;
pub const PARAM_EnumProfile: u32 = 8;
pub const PARAM_Profile: u32 = 9;
pub const PARAM_EnumRoute: u32 = 12;
pub const PARAM_Route: u32 = 13;

// props keys (spa/param/props.h)
pub const PROP_volume: u32 = 0x10003;
pub const PROP_mute: u32 = 0x10004;
pub const PROP_channelVolumes: u32 = 0x10008;
pub const PROP_volumeBase: u32 = 0x10009;
pub const PROP_volumeStep: u32 = 0x1000a;
pub const PROP_channelMap: u32 = 0x1000b;
pub const PROP_monitorMute: u32 = 0x1000c;
pub const PROP_monitorVolumes: u32 = 0x1000d;
pub const PROP_latencyOffsetNsec: u32 = 0x1000e;
pub const PROP_softMute: u32 = 0x1000f;
pub const PROP_softVolumes: u32 = 0x10010;

// profile keys (spa/param/profile.h)
pub const PROFILE_index: u32 = 1;
pub const PROFILE_name: u32 = 2;
pub const PROFILE_description: u32 = 3;
pub const PROFILE_priority: u32 = 4;
pub const PROFILE_available: u32 = 5;
pub const PROFILE_classes: u32 = 7;

// route keys (spa/param/route.h)
pub const ROUTE_index: u32 = 1;
pub const ROUTE_direction: u32 = 2;
pub const ROUTE_device: u32 = 3;
pub const ROUTE_name: u32 = 4;
pub const ROUTE_description: u32 = 5;
pub const ROUTE_priority: u32 = 6;
pub const ROUTE_available: u32 = 7;
pub const ROUTE_info: u32 = 8;
pub const ROUTE_profiles: u32 = 9;
pub const ROUTE_props: u32 = 10;
pub const ROUTE_devices: u32 = 11;
pub const ROUTE_profile: u32 = 12;
pub const ROUTE_save: u32 = 13;

// format keys (spa/param/format.h, spa/param/audio/raw.h)
pub const FORMAT_mediaType: u32 = 1;
pub const FORMAT_mediaSubtype: u32 = 2;
pub const FORMAT_AUDIO_format: u32 = 0x10001;
pub const FORMAT_AUDIO_rate: u32 = 0x10003;
pub const FORMAT_AUDIO_channels: u32 = 0x10004;

pub const MEDIA_TYPE_audio: u32 = 1;
pub const MEDIA_SUBTYPE_raw: u32 = 1;
pub const AUDIO_FORMAT_F32_LE: u32 = 0x11b;

pub const availability_unknown: u32 = 0;
pub const availability_no: u32 = 1;
pub const availability_yes: u32 = 2;

pub const Pod = extern struct {
    size: u32,
    pod_type: u32,
};

pub const ObjectBody = extern struct {
    type_: u32,
    id: u32,
};

pub const Prop = extern struct {
    key: u32,
    flags: u32,
    value: Pod,
};

fn podBytes(pod: *const Pod) [*]const u8 {
    return @ptrCast(pod);
}

pub fn totalSize(pod: *const Pod) usize {
    return 8 + pod.size;
}

/// Body type of an object pod (e.g. OBJECT_Props).
pub fn objectType(pod: *const Pod) u32 {
    const body: *const ObjectBody = @ptrFromInt(@intFromPtr(pod) + 8);
    return body.type_;
}

/// Param id of an object pod (e.g. PARAM_Props / PARAM_EnumRoute).
pub fn objectId(pod: *const Pod) u32 {
    const body: *const ObjectBody = @ptrFromInt(@intFromPtr(pod) + 8);
    return body.id;
}

fn propInside(pod: *const Pod, prop: *const Prop) bool {
    const base = @intFromPtr(pod);
    const total = totalSize(pod);
    const off = @intFromPtr(prop) - base;
    if (off + 16 > total) return false;
    return (total - (off + 16)) >= prop.value.size;
}

/// First property of an object pod, or null.
pub fn firstProp(pod: *const Pod) ?*const Prop {
    if (pod.pod_type != TYPE_OBJECT) return null;
    const p: *const Prop = @ptrFromInt(@intFromPtr(pod) + 16);
    return if (propInside(pod, p)) p else null;
}

/// Next property after `prop`, or null at the end. Property values are
/// padded to 8 bytes, exactly like `spa_pod_prop_next`.
pub fn nextProp(pod: *const Pod, prop: *const Prop) ?*const Prop {
    const base = @intFromPtr(pod);
    const off = @intFromPtr(prop) - base;
    const next_off = std.mem.alignForward(usize, off + 16 + prop.value.size, 8);
    const p: *const Prop = @ptrFromInt(base + next_off);
    return if (propInside(pod, p)) p else null;
}

pub fn findProp(pod: *const Pod, key: u32) ?*const Prop {
    var it = firstProp(pod);
    while (it) |p| : (it = nextProp(pod, p)) {
        if (p.key == key) return p;
    }
    return null;
}

// ── value accessors ─────────────────────────────────────────────────────────

pub const TYPE_CHOICE: u32 = 19;

/// The pod that holds a property's effective value. Choice pods — how the
/// server expresses "current value plus the range/list around it", e.g. in
/// EnumFormat — keep that value in their child pod; everything else is its
/// own value.
pub fn propValue(prop: *const Prop) *const Pod {
    if (prop.value.pod_type != TYPE_CHOICE) return &prop.value;
    // spa_pod_choice_body: type u32, flags u32, then the child pod.
    return @ptrFromInt(@intFromPtr(&prop.value) + 16);
}

fn valueBody(prop: *const Prop) [*]const u8 {
    return podBytes(propValue(prop)) + 8;
}

pub fn valueFloat(prop: *const Prop) f32 {
    if (propValue(prop).pod_type != TYPE_FLOAT) return 0;
    return @bitCast(std.mem.readInt(u32, valueBody(prop)[0..4], .little));
}

pub fn valueInt(prop: *const Prop) i32 {
    if (propValue(prop).pod_type != TYPE_INT) return 0;
    return @bitCast(std.mem.readInt(u32, valueBody(prop)[0..4], .little));
}

pub fn valueId(prop: *const Prop) u32 {
    if (propValue(prop).pod_type != TYPE_ID) return 0;
    return std.mem.readInt(u32, valueBody(prop)[0..4], .little);
}

pub fn valueBool(prop: *const Prop) bool {
    if (propValue(prop).pod_type != TYPE_BOOL) return false;
    return std.mem.readInt(u32, valueBody(prop)[0..4], .little) != 0;
}

pub fn valueString(prop: *const Prop) []const u8 {
    if (propValue(prop).pod_type != TYPE_STRING) return "";
    const size = propValue(prop).size;
    const n: usize = if (size > 0) size - 1 else 0;
    const body = valueBody(prop);
    return body[0..n];
}

pub const ArrayView = struct {
    child_size: u32,
    child_type: u32,
    count: usize,
    data: [*]const u8,
};

pub fn valueArray(prop: *const Prop) ?ArrayView {
    const v = propValue(prop);
    if (v.pod_type != TYPE_ARRAY) return null;
    if (v.size < 8) return null;
    const body = valueBody(prop);
    const child_size = std.mem.readInt(u32, body[0..4], .little);
    const child_type = std.mem.readInt(u32, body[4..8], .little);
    const nbytes: usize = v.size - 8;
    if (child_size == 0) return null;
    return .{
        .child_size = child_size,
        .child_type = child_type,
        .count = nbytes / child_size,
        .data = body + 8,
    };
}

pub fn valueFloatArray(prop: *const Prop) []const f32 {
    const a = valueArray(prop) orelse return &.{};
    if (a.child_type != TYPE_FLOAT or a.child_size != 4) return &.{};
    const ptr: [*]const f32 = @ptrCast(@alignCast(a.data));
    return ptr[0..a.count];
}

pub fn valueIdArray(prop: *const Prop) []const u32 {
    const a = valueArray(prop) orelse return &.{};
    if (a.child_type != TYPE_ID or a.child_size != 4) return &.{};
    const ptr: [*]const u32 = @ptrCast(@alignCast(a.data));
    return ptr[0..a.count];
}

pub fn valueIntArray(prop: *const Prop) []const i32 {
    const a = valueArray(prop) orelse return &.{};
    if (a.child_type != TYPE_INT or a.child_size != 4) return &.{};
    const ptr: [*]const i32 = @ptrCast(@alignCast(a.data));
    return ptr[0..a.count];
}

// ── builder ─────────────────────────────────────────────────────────────────

/// Byte-identical builder for the pod shapes this app writes: one object with
/// primitive or array properties. Little-endian hosts only (x86_64/aarch64).
pub const Builder = struct {
    buf: []u8,
    pos: usize = 0,

    pub fn init(buf: []u8) Builder {
        // Pod pointers are 4-byte aligned by the ABI; every caller hands in
        // an 8-byte-aligned buffer (this keeps `@ptrFromInt` casts sound).
        assert(@intFromPtr(buf.ptr) % 8 == 0);
        return .{ .buf = buf };
    }

    fn pad(self: *Builder) void {
        const rem = self.pos & 7;
        if (rem == 0) return;
        const n = 8 - rem;
        assert(self.pos + n <= self.buf.len);
        @memset(self.buf[self.pos..][0..n], 0);
        self.pos += n;
    }

    fn u32Put(self: *Builder, v: u32) void {
        assert(self.pos + 4 <= self.buf.len);
        std.mem.writeInt(u32, self.buf[self.pos..][0..4], v, .little);
        self.pos += 4;
    }

    fn f32Put(self: *Builder, v: f32) void {
        self.u32Put(@bitCast(v));
    }

    fn bytesPut(self: *Builder, v: []const u8) void {
        assert(self.pos + v.len <= self.buf.len);
        @memcpy(self.buf[self.pos..][0..v.len], v);
        self.pos += v.len;
    }

    pub fn beginObject(self: *Builder, object_type: u32, object_id: u32) void {
        self.pos = 0;
        // pod header (size filled in by finish) + object body
        self.u32Put(0);
        self.u32Put(TYPE_OBJECT);
        self.u32Put(object_type);
        self.u32Put(object_id);
    }

    fn beginProp(self: *Builder, key: u32, value_type: u32, value_body_size: u32) void {
        self.pad();
        self.u32Put(key);
        self.u32Put(0); // flags
        self.u32Put(value_body_size);
        self.u32Put(value_type);
    }

    pub fn endObject(self: *Builder) *const Pod {
        self.pad();
        const total = self.pos;
        std.mem.writeInt(u32, self.buf[0..4], @intCast(total - 8), .little);
        const pod: *const Pod = @ptrFromInt(@intFromPtr(self.buf.ptr));
        return pod;
    }

    pub fn propFloat(self: *Builder, key: u32, v: f32) void {
        self.beginProp(key, TYPE_FLOAT, 4);
        self.f32Put(v);
    }

    pub fn propInt(self: *Builder, key: u32, v: i32) void {
        self.beginProp(key, TYPE_INT, 4);
        self.u32Put(@bitCast(v));
    }

    pub fn propId(self: *Builder, key: u32, v: u32) void {
        self.beginProp(key, TYPE_ID, 4);
        self.u32Put(v);
    }

    pub fn propBool(self: *Builder, key: u32, v: bool) void {
        self.beginProp(key, TYPE_BOOL, 4);
        self.u32Put(if (v) 1 else 0);
    }

    pub fn propString(self: *Builder, key: u32, v: []const u8) void {
        self.beginProp(key, TYPE_STRING, @intCast(v.len + 1));
        self.bytesPut(v);
        assert(self.pos + 1 <= self.buf.len);
        self.buf[self.pos] = 0;
        self.pos += 1;
    }

    pub fn propFloatArray(self: *Builder, key: u32, values: []const f32) void {
        self.beginProp(key, TYPE_ARRAY, @intCast(8 + 4 * values.len));
        self.u32Put(4);
        self.u32Put(TYPE_FLOAT);
        for (values) |v| self.f32Put(v);
    }

    pub fn propIdArray(self: *Builder, key: u32, values: []const u32) void {
        self.beginProp(key, TYPE_ARRAY, @intCast(8 + 4 * values.len));
        self.u32Put(4);
        self.u32Put(TYPE_ID);
        for (values) |v| self.u32Put(v);
    }

    pub fn propIntArray(self: *Builder, key: u32, values: []const i32) void {
        self.beginProp(key, TYPE_ARRAY, @intCast(8 + 4 * values.len));
        self.u32Put(4);
        self.u32Put(TYPE_INT);
        for (values) |v| self.u32Put(@bitCast(v));
    }

    /// A property whose value is itself a pod (e.g. the `props` object inside
    /// a SPA_PARAM_Route). The inner pod's body is inlined, exactly like
    /// `spa_pod_builder_push_object` + `pop` nests in C.
    pub fn propPodBody(self: *Builder, key: u32, inner: *const Pod) void {
        self.beginProp(key, inner.pod_type, inner.size);
        self.bytesPut((podBytes(inner) + 8)[0..inner.size]);
    }
};

/// Build an audio EnumFormat pod for a capture stream (fixed format).
pub fn audioEnumFormat(buf: []u8, rate: i32, channels: i32) *const Pod {
    var b = Builder.init(buf);
    b.beginObject(OBJECT_Format, PARAM_EnumFormat);
    b.propId(FORMAT_mediaType, MEDIA_TYPE_audio);
    b.propId(FORMAT_mediaSubtype, MEDIA_SUBTYPE_raw);
    b.propId(FORMAT_AUDIO_format, AUDIO_FORMAT_F32_LE);
    b.propInt(FORMAT_AUDIO_rate, rate);
    b.propInt(FORMAT_AUDIO_channels, channels);
    return b.endObject();
}

/// Props pod carrying a uniform volume (0.0 = silence, 1.0 = 0 dB).
pub fn propsVolume(buf: []u8, volume: f32) *const Pod {
    var b = Builder.init(buf);
    b.beginObject(OBJECT_Props, PARAM_Props);
    b.propFloat(PROP_volume, volume);
    return b.endObject();
}

pub fn propsMute(buf: []u8, mute: bool) *const Pod {
    var b = Builder.init(buf);
    b.beginObject(OBJECT_Props, PARAM_Props);
    b.propBool(PROP_mute, mute);
    return b.endObject();
}

/// Props pod carrying per-channel volumes (linear amplitudes, i.e. the
/// `channelVolumes` values as PipeWire reports them).
pub fn propsChannelVolumes(buf: []u8, volumes: []const f32) *const Pod {
    var b = Builder.init(buf);
    b.beginObject(OBJECT_Props, PARAM_Props);
    b.propFloatArray(PROP_channelVolumes, volumes);
    return b.endObject();
}

/// Props pod carrying the monitor volumes (what a monitor source's slider
/// writes, mirroring pipewire-pulse).
pub fn propsMonitorVolumes(buf: []u8, volumes: []const f32) *const Pod {
    var b = Builder.init(buf);
    b.beginObject(OBJECT_Props, PARAM_Props);
    b.propFloatArray(PROP_monitorVolumes, volumes);
    return b.endObject();
}

pub fn propsMonitorMute(buf: []u8, mute: bool) *const Pod {
    var b = Builder.init(buf);
    b.beginObject(OBJECT_Props, PARAM_Props);
    b.propBool(PROP_monitorMute, mute);
    return b.endObject();
}

/// A SPA_PARAM_Route pod that sets a card route's volume and/or mute and
/// asks the session manager to persist it — the exact write pipewire-pulse
/// performs when a hardware sink/source volume changes over the pulse API.
pub fn routeVolume(buf: []u8, index: i32, device: i32, volumes: ?[]const f32, mute: ?bool) *const Pod {
    var scratch: [256]u8 align(8) = undefined;
    var inner = Builder.init(&scratch);
    inner.beginObject(OBJECT_Props, PARAM_Props);
    if (volumes) |v| inner.propFloatArray(PROP_channelVolumes, v);
    if (mute) |m| inner.propBool(PROP_mute, m);
    const props = inner.endObject();

    var b = Builder.init(buf);
    b.beginObject(OBJECT_ParamRoute, PARAM_Route);
    b.propInt(ROUTE_index, index);
    if (device >= 0) b.propInt(ROUTE_device, device);
    b.propPodBody(ROUTE_props, props);
    b.propBool(ROUTE_save, true);
    return b.endObject();
}

pub fn profileIndex(buf: []u8, index: i32) *const Pod {
    var b = Builder.init(buf);
    b.beginObject(OBJECT_ParamProfile, PARAM_Profile);
    b.propInt(PROFILE_index, index);
    return b.endObject();
}

pub fn routeIndex(buf: []u8, index: i32, device: i32) *const Pod {
    var b = Builder.init(buf);
    b.beginObject(OBJECT_ParamRoute, PARAM_Route);
    b.propInt(ROUTE_index, index);
    if (device >= 0) b.propInt(ROUTE_device, device);
    return b.endObject();
}

/// The port-change write pipewire-pulse performs (set_card_port): route index
/// plus the node's `card.profile.device`, marked for the session manager to
/// save.
pub fn routePort(buf: []u8, index: i32, device: i32) *const Pod {
    var b = Builder.init(buf);
    b.beginObject(OBJECT_ParamRoute, PARAM_Route);
    b.propInt(ROUTE_index, index);
    if (device >= 0) b.propInt(ROUTE_device, device);
    b.propBool(ROUTE_save, true);
    return b.endObject();
}

// ── tests ───────────────────────────────────────────────────────────────────

const testing = std.testing;

fn hexToBytes(comptime hex: []const u8, out: []u8) []u8 {
    return std.fmt.hexToBytes(out, hex) catch unreachable;
}

test "builder matches C reference: volume only" {
    var buf: [128]u8 align(8) = undefined;
    const pod = propsVolume(&buf, 0.75);
    const expected = "200000000f0000000200040002000000030001000000000004000000060000000000403f00000000";
    var want: [64]u8 = undefined;
    try testing.expectEqualSlices(u8, hexToBytes(expected, &want), podBytes(pod)[0..totalSize(pod)]);
    try testing.expectEqual(@as(u32, 0x20), pod.size);
    try testing.expectEqual(OBJECT_Props, objectType(pod));
    try testing.expectEqual(PARAM_Props, objectId(pod));
    const p = findProp(pod, PROP_volume).?;
    try testing.expectEqual(@as(f32, 0.75), valueFloat(p));
}

test "builder matches C reference: volume + mute" {
    var buf: [128]u8 align(8) = undefined;
    var b = Builder.init(&buf);
    b.beginObject(OBJECT_Props, PARAM_Props);
    b.propFloat(PROP_volume, 0.5);
    b.propBool(PROP_mute, true);
    const pod = b.endObject();
    const expected = "380000000f0000000200040002000000030001000000000004000000060000000000003f00000000040001000000000004000000020000000100000000000000";
    var want: [64]u8 = undefined;
    try testing.expectEqualSlices(u8, hexToBytes(expected, &want), podBytes(pod)[0..totalSize(pod)]);
    try testing.expectEqual(true, valueBool(findProp(pod, PROP_mute).?));
    try testing.expectEqual(@as(f32, 0.5), valueFloat(findProp(pod, PROP_volume).?));
}

test "builder matches C reference: channelVolumes 2 and 1" {
    var buf: [128]u8 align(8) = undefined;
    const pod2 = propsChannelVolumes(&buf, &.{ 0.5, 0.25 });
    const expected2 = "280000000f00000002000400020000000800010000000000100000000d00000004000000060000000000003f0000803e";
    var want: [64]u8 = undefined;
    try testing.expectEqualSlices(u8, hexToBytes(expected2, &want), podBytes(pod2)[0..totalSize(pod2)]);
    try testing.expectEqualSlices(f32, &.{ 0.5, 0.25 }, valueFloatArray(findProp(pod2, PROP_channelVolumes).?));

    const pod1 = propsChannelVolumes(&buf, &.{0.5});
    const expected1 = "280000000f000000020004000200000008000100000000000c0000000d00000004000000060000000000003f00000000";
    try testing.expectEqualSlices(u8, hexToBytes(expected1, &want), podBytes(pod1)[0..totalSize(pod1)]);
    try testing.expectEqualSlices(f32, &.{0.5}, valueFloatArray(findProp(pod1, PROP_channelVolumes).?));
}

test "builder matches C reference: profile and route" {
    var buf: [128]u8 align(8) = undefined;
    const prof = profileIndex(&buf, 131073);
    const expected_prof = "200000000f0000000700040009000000010000000000000004000000040000000100020000000000";
    var want: [64]u8 = undefined;
    try testing.expectEqualSlices(u8, hexToBytes(expected_prof, &want), podBytes(prof)[0..totalSize(prof)]);
    try testing.expectEqual(@as(i32, 131073), valueInt(findProp(prof, PROFILE_index).?));

    const route = routeIndex(&buf, 5, 1);
    const expected_route = "380000000f000000090004000d000000010000000000000004000000040000000500000000000000030000000000000004000000040000000100000000000000";
    try testing.expectEqualSlices(u8, hexToBytes(expected_route, &want), podBytes(route)[0..totalSize(route)]);
    try testing.expectEqual(@as(i32, 5), valueInt(findProp(route, ROUTE_index).?));
    try testing.expectEqual(@as(i32, 1), valueInt(findProp(route, ROUTE_device).?));
}

test "builder matches C reference: route port (pulse set_card_port)" {
    // Generated by /tmp/opencode/pwprobe/podref_route2.c (official C builder,
    // same shape as module-protocol-pulse: set_card_port).
    var buf: [128]u8 align(8) = undefined;
    const port = routePort(&buf, 5, 1);
    const expected = "500000000f000000090004000d0000000100000000000000040000000400000005000000000000000300000000000000040000000400000001000000000000000d0000000000000004000000020000000100000000000000";
    var want: [128]u8 = undefined;
    try testing.expectEqualSlices(u8, hexToBytes(expected, &want), podBytes(port)[0..totalSize(port)]);
    try testing.expectEqual(OBJECT_ParamRoute, objectType(port));
    try testing.expectEqual(PARAM_Route, objectId(port));
    try testing.expectEqual(@as(i32, 5), valueInt(findProp(port, ROUTE_index).?));
    try testing.expectEqual(@as(i32, 1), valueInt(findProp(port, ROUTE_device).?));
    try testing.expectEqual(true, valueBool(findProp(port, ROUTE_save).?));
}

test "builder matches C reference: route volume (pulse write)" {
    // Generated by /tmp/opencode/pwprobe/podref_route.c (official C builder,
    // same shape as module-protocol-pulse: set_card_volume_mute_delay).
    var buf: [512]u8 align(8) = undefined;
    const p = routeVolume(&buf, 5, 1, &.{ 0.5, 0.25 }, true);
    const expected = "";
    var want: [512]u8 = undefined;
    try testing.expectEqual(@as(usize, 168), totalSize(p));
    try testing.expectEqualSlices(u8, hexToBytes(expected, &want), podBytes(p)[0..totalSize(p)]);
    try testing.expectEqual(OBJECT_ParamRoute, objectType(p));
    try testing.expectEqual(PARAM_Route, objectId(p));
    try testing.expectEqual(@as(i32, 5), valueInt(findProp(p, ROUTE_index).?));
    try testing.expectEqual(@as(i32, 1), valueInt(findProp(p, ROUTE_device).?));
    try testing.expectEqual(true, valueBool(findProp(p, ROUTE_save).?));

    const props = findProp(p, ROUTE_props).?;
    try testing.expectEqual(TYPE_OBJECT, props.value.pod_type);
    const inner: *const Pod = &props.value;
    try testing.expectEqual(OBJECT_Props, objectType(inner));
    try testing.expectEqual(PARAM_Props, objectId(inner));
    try testing.expectEqualSlices(f32, &.{ 0.5, 0.25 }, valueFloatArray(findProp(inner, PROP_channelVolumes).?));
    try testing.expectEqual(true, valueBool(findProp(inner, PROP_mute).?));
}

test "builder matches C reference: mute only" {
    var buf: [128]u8 align(8) = undefined;
    const pod = propsMute(&buf, true);
    const expected = "200000000f0000000200040002000000040001000000000004000000020000000100000000000000";
    var want: [64]u8 = undefined;
    try testing.expectEqualSlices(u8, hexToBytes(expected, &want), podBytes(pod)[0..totalSize(pod)]);
}

test "builder matches C reference: enum format" {
    var buf: [256]u8 align(8) = undefined;
    const pod = audioEnumFormat(&buf, 48000, 2);
    const expected = "800000000f0000000300040003000000010000000000000004000000030000000100000000000000020000000000000004000000030000000100000000000000010001000000000004000000030000001b010000000000000300010000000000040000000400000080bb000000000000040001000000000004000000040000000200000000000000";
    var want: [256]u8 = undefined;
