test "reader walks every prop in a multi-prop pod" {
    var buf: [256]u8 align(8) = undefined;
    var b = Builder.init(&buf);
    b.beginObject(OBJECT_Props, PARAM_Props);
    b.propFloat(PROP_volume, 1.5);
    b.propBool(PROP_mute, false);
    b.propFloatArray(PROP_channelVolumes, &.{ 0.1, 0.2, 0.3 });
    b.propIdArray(PROP_channelMap, &.{ 1, 2 });
    const pod = b.endObject();
    var n: usize = 0;
    var it = firstProp(pod);
    while (it) |p| : (it = nextProp(pod, p)) n += 1;
    try testing.expectEqual(@as(usize, 4), n);
    try testing.expectEqual(@as(f32, 1.5), valueFloat(findProp(pod, PROP_volume).?));
    try testing.expectEqual(false, valueBool(findProp(pod, PROP_mute).?));
    try testing.expectEqualSlices(f32, &.{ 0.1, 0.2, 0.3 }, valueFloatArray(findProp(pod, PROP_channelVolumes).?));
    try testing.expectEqualSlices(u32, &.{ 1, 2 }, valueIdArray(findProp(pod, PROP_channelMap).?));
}

test "objectType survives a pod produced by PipeWire (route sample)" {
    // First EnumRoute object captured from `pw-cli enum-params <device> EnumRoute`
    // on this machine (UMC202HD): index 0, direction Input, name "analog-stereo".
    // Only the header prefix is asserted here; see graph tests for full parse.
    var buf: [512]u8 align(8) = undefined;
    var b = Builder.init(&buf);
    b.beginObject(OBJECT_ParamRoute, PARAM_EnumRoute);
    b.propInt(ROUTE_index, 0);
    b.propId(ROUTE_direction, 1);
    const pod = b.endObject();
    try testing.expectEqual(OBJECT_ParamRoute, objectType(pod));
    try testing.expectEqual(PARAM_EnumRoute, objectId(pod));
    try testing.expectEqual(@as(i32, 0), valueInt(findProp(pod, ROUTE_index).?));
}

test "choice props expose the value from their child pod" {
    // The EnumFormat the server hands to a capture stream wraps every prop in
    // an SPA_TYPE_Choice pod. Shape captured live from a meter stream:
    //   object(Format/EnumFormat) { channels = choice(None, int 2) }
    const words = [_]u32{
        44, TYPE_OBJECT, OBJECT_Format, PARAM_EnumFormat, // pod header + body
        FORMAT_AUDIO_channels, 0, // prop key + flags
        20, TYPE_CHOICE, // choice value pod: body size, type
        0, 0, // SPA_CHOICE_None, no flags
        4, TYPE_INT, 2, // child pod holding the actual value
    };
    const pod: *const Pod = @ptrCast(&words);
    try testing.expectEqual(OBJECT_Format, objectType(pod));
    try testing.expectEqual(PARAM_EnumFormat, objectId(pod));
    const prop = findProp(pod, FORMAT_AUDIO_channels).?;
    try testing.expectEqual(TYPE_CHOICE, prop.value.pod_type);
    try testing.expectEqual(@as(i32, 2), valueInt(prop));
    // a missing key still reports nothing rather than a stale neighbour
    try testing.expect(findProp(pod, FORMAT_AUDIO_rate) == null);
}
